@Override public Renderer[] createRenderers(Handler eventHandler,VideoRendererEventListener videoRendererEventListener,AudioRendererEventListener audioRendererEventListener,TextOutput textRendererOutput,MetadataOutput metadataRendererOutput){
  int rendererCount=removeAudio || removeVideo ? 1 : 2;
  Renderer[] renderers=new Renderer[rendererCount];
  int index=0;
  if (!removeAudio) {
    renderers[index]=new ExoAssetLoaderAudioRenderer(decoderFactory,mediaClock,assetLoaderListener);
    index++;
  }
  if (!removeVideo) {
    renderers[index]=new ExoAssetLoaderVideoRenderer(flattenForSlowMotion,decoderFactory,forceInterpretHdrAsSdr,mediaClock,assetLoaderListener);
    index++;
  }
  return renderers;
}
